mapper.sql:
AND EXISTS (
    SELECT 1 FROM TM_USERXM OWNER
 LEFT JOIN TM_REPORT REPORT ON #{tagtType} = #{targetReport} AND REPORT.REPT_NUMB = #{tagtNumb}
     WHERE OWNER.USER_STAT = #{userStatActive}
       AND EXISTS (SELECT 1 FROM TM_USERXM ACTOR WHERE ACTOR.USER_NUMB = #{userNumb} AND ACTOR.USER_STAT = #{userStatActive})
       AND (   (#{tagtType} = #{targetReport} AND REPORT.USER_NUMB = OWNER.USER_NUMB
                 AND (REPORT.USER_NUMB = #{userNumb} OR (REPORT.PUBC_YSNO = #{commYes} AND REPORT.REPT_STAT != #{reptStatRead})))
            OR (#{tagtType} = #{targetProfile} AND OWNER.PROF_NUMB = #{tagtNumb}
                AND (OWNER.USER_NUMB = #{userNumb} OR EXISTS (
                    SELECT 1 FROM TB_FOLLOW F
                     WHERE F.USER_NUMB = #{userNumb}
                       AND F.FLOW_NUMB = OWNER.USER_NUMB
                )))
            OR (#{tagtType} = #{targetBackground} AND OWNER.BGIM_NUMB = #{tagtNumb}
                AND (OWNER.USER_NUMB = #{userNumb} OR EXISTS (
                    SELECT 1 FROM TB_FOLLOW F
                     WHERE F.USER_NUMB = #{userNumb}
                       AND F.FLOW_NUMB = OWNER.USER_NUMB
                ))))
)

mapper.update:

UPDATE TB_REPLXX R SET R.REPL_CNTN = #{replCntn}, R.UPDT_DATE = CURRENT_TIMESTAMP
 WHERE R.TAGT_TYPE = #{tagtType} AND R.TAGT_NUMB = #{tagtNumb} AND R.REPL_NUMB = #{replNumb}
   AND R.USER_NUMB = #{userNumb} AND R.DELT_YSNO = #{commNo}
   AND SHA2(CONCAT_WS('|', COALESCE(R.REPL_CNTN, ''), COALESCE(R.DELT_YSNO, '')), 256) = #{editVersion}
   AND EXISTS (SELECT 1 FROM TM_USERXM U WHERE U.USER_NUMB = #{userNumb} AND U.USER_STAT = #{userStatActive})


UPDATE TB_REPLXX R SET R.DELT_YSNO = #{commYes}, R.UPDT_DATE = CURRENT_TIMESTAMP
 WHERE R.TAGT_TYPE = #{tagtType} AND R.TAGT_NUMB = #{tagtNumb} AND R.REPL_NUMB = #{replNumb}
   AND R.USER_NUMB = #{userNumb} AND R.DELT_YSNO = #{commNo}
   AND EXISTS (SELECT 1 FROM TM_USERXM U WHERE U.USER_NUMB = #{userNumb} AND U.USER_STAT = #{userStatActive})

mapper.select:

SELECT #{tagtType} AS TAGT_TYPE, #{tagtNumb} AS TAGT_NUMB, #{replNumb} AS REPL_NUMB
     , COUNT(U.USER_NUMB) AS LIKE_CNT, IF(MAX(IF(L.USER_NUMB = #{userNumb}, 1, 0)) = 1, #{commYes}, #{commNo}) AS LIKE_YSNO
  FROM TB_LIKEXX L JOIN TM_USERXM U ON U.USER_NUMB = L.USER_NUMB AND U.USER_STAT = #{userStatActive}
 WHERE L.TAGT_TYPE = #{likeTargetReply} AND L.TAGT_NUMB = #{replNumb}


   SELECT CASE WHEN #{tagtType} = #{targetReport} THEN R.USER_NUMB ELSE U.USER_NUMB END AS TARGET_USER_NUMB
        , PU.USER_NUMB AS PARENT_USER_NUMB
        , CASE WHEN #{tagtType} = #{targetReport} THEN R.RPAL_YSNO ELSE #{commYes} END AS REPLY_ALIM_YSNO
        , CASE WHEN #{tagtType} = #{targetProfile} THEN #{alimReplyProfile}
               WHEN #{tagtType} = #{targetBackground} THEN #{alimReplyBackground} ELSE #{alimReplyReport} END AS ALIM_TEMP_CODE
        , R.REPT_NUMB AS ALIM_TAGT_NUMB
     FROM (SELECT 1 AS DUMMY) D
LEFT JOIN TM_REPORT R ON #{tagtType} = #{targetReport} AND R.REPT_NUMB = #{tagtNumb}
LEFT JOIN TM_USERXM U ON (#{tagtType} = #{targetProfile} AND U.PROF_NUMB = #{tagtNumb})
                     OR (#{tagtType} = #{targetBackground} AND U.BGIM_NUMB = #{tagtNumb})
LEFT JOIN TB_REPLXX P ON P.REPL_NUMB = #{uperNumb,jdbcType=NUMERIC}
                     AND P.TAGT_TYPE = #{tagtType}
                     AND P.TAGT_NUMB = #{tagtNumb}
                     AND P.DELT_YSNO = #{commNo}
LEFT JOIN TM_USERXM PU ON PU.USER_NUMB = P.USER_NUMB
                      AND PU.USER_STAT = #{userStatActive}
